def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    # If a is empty, return empty list
    if not a_intervals:
        return []

    # If b is empty, merge and return a
    if not b_intervals:
        return merge_intervals(a_intervals)

    # Merge b intervals for efficient subtraction
    b_merged = merge_intervals(b_intervals)

    # Subtract b from a
    result = []
    for a_start, a_end in a_intervals:
        current_ranges = [(a_start, a_end)]

        # Subtract each b interval from current ranges
        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append((curr_start, curr_end))
                # Partial overlap
                else:
                    if curr_start < b_start:
                        new_ranges.append((curr_start, b_start))
                    if curr_end > b_end:
                        new_ranges.append((b_end, curr_end))
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge adjacent/overlapping intervals
    result = merge_intervals(result)

    return [[start, end] for start, end in result]

def merge_intervals(intervals):
    if not intervals:
        return []

    intervals = sorted(intervals)
    merged = [intervals[0]]

    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            # Overlapping or touching, merge them
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

